unitsize(0.8cm);
for (int i=0; i<7; ++i) {
for (int j=0; j<4; ++j) {
dot((i,j));
};}
label("$F$",(5,3),N);
label("$C$",(4,2),N);
draw((2,0)--(5,3)--(0,3)--(6,0)--cycle,linewidth(0.7));
label("$A$",(0,3),W);
label("$B$",(6,0),E);
label("$D$",(2,0),S);
label("$E$",(3.4,1.3),N);
dot((3.4,1.3));
label("$C$",(4,2),N);

[/asy]

